using System.Reflection.PortableExecutable;
using System.Reflection.Metadata;
using System.Security.Cryptography;
using System.Text.Json;
using var file=File.OpenRead(args[0]);using var pe=new PEReader(file);var md=pe.GetMetadataReader();int rva=pe.PEHeaders.CorHeader!.ResourcesDirectory.RelativeVirtualAddress;var names=new List<object>();
using var plan=JsonDocument.Parse(File.ReadAllBytes(args[1]));var keys=new Dictionary<string,string>{{"ak","acoustic"},{"lk","linguistic"},{"engine","engine"},{"line30","spatial30"},{"line50","physical50"},{"separation","separation"},{"case","cases"},{"publication","publication"},{"normalization","normalization"},{"circles","circles"}};var pins=plan.RootElement.GetProperty("files").EnumerateArray().Where(x=>keys.ContainsKey(x.GetProperty("name").GetString()!)).ToDictionary(x=>"BlurMask.ExperimentalInk."+keys[x.GetProperty("name").GetString()!]);
foreach(var handle in md.ManifestResources){var row=md.GetManifestResource(handle);string name=md.GetString(row.Name);if(!pins.TryGetValue(name,out var pin))continue;if(!row.Implementation.IsNil)throw new Exception("Embedded required");var reader=pe.GetSectionData(checked(rva+(int)row.Offset)).GetReader();int n=reader.ReadInt32();if(n<1||n>8000000)throw new Exception("Bounded embedded bytes");var bytes=reader.ReadBytes(n);string sha=Convert.ToHexStringLower(SHA256.HashData(bytes));if(n!=pin.GetProperty("bytes").GetInt64()||sha!=pin.GetProperty("sha256").GetString())throw new Exception(name);names.Add(new{Name=name,Bytes=n,Sha256=sha});}
if(names.Count!=10)throw new Exception("Exact ten");File.WriteAllText(args[2],JsonSerializer.Serialize(new{Scope="Read-only PE resource table. Target app NEVER loaded/executed; no NN",Resources=names},new JsonSerializerOptions{WriteIndented=true}));
